'use strict';
const FactorEngine={
 select(rows,year,severity){return rows.filter(r=>r.kind==='vehicle'&&r.year===+year&&r.severity===severity);},
 pairs(rows){const map=new Map();for(const r of rows){if(r.factor.startsWith('Any ')||r.factor.startsWith('Vehicles ')||r.factor==='Not mapped to specific RSF')continue;const k=r.section+'|'+r.factor;if(!map.has(k))map.set(k,{factor:r.factor,section:r.section});map.get(k)[r.mode]=r;}return [...map.values()].sort((a,b)=>(b.direct?.percent??b.converted?.percent??-1)-(a.direct?.percent??a.converted?.percent??-1)||a.factor.localeCompare(b.factor));},
 csv(pairs,year,severity){const q=v=>'"'+String(v??'Unavailable').replace(/"/g,'""')+'"';return [['Source','DfT RAS0702'],['Year',year],['Severity',severity],['Unit','Motorcycles in eligible collisions; factors assigned to motorcycle; not causal effects'],['Factor','Section','Converted %','Converted count','Converted denominator','Direct %','Direct count','Direct denominator'],...pairs.map(p=>[p.factor,p.section,p.converted?.percent,p.converted?.count,p.converted?.denominator,p.direct?.percent,p.direct?.count,p.direct?.denominator])].map(r=>r.map(q).join(',')).join('\r\n');}
};
if(typeof module!=='undefined')module.exports=FactorEngine;
if(typeof document!=='undefined'){
const $=id=>document.getElementById('f-'+id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=new Intl.NumberFormat('en-GB'),num=v=>v==null?'Unavailable':fmt.format(v),pct=v=>v==null?'Unavailable':v+'%';let rows=[],pairs=[];
const table=(heads,data)=>'<table><thead><tr>'+heads.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+data.map(r=>'<tr>'+r.map((v,i)=>i?'<td>'+esc(v)+'</td>':'<th scope="row">'+esc(v)+'</th>').join('')+'</tr>').join('')+'</tbody></table>';
function renderTrend(){const f=$('factor').value,sev=$('severity').value;$('trend').innerHTML=table(['Year','Converted %','Eligible converted motorcycles','Direct %','Eligible direct motorcycles'],[2020,2021,2022,2023,2024,2025].map(y=>{const a=rows.filter(r=>r.kind==='vehicle'&&r.year===y&&r.severity===sev&&r.factor===f);const c=a.find(r=>r.mode==='converted'),d=a.find(r=>r.mode==='direct');return[y,pct(c?.percent),num(c?.denominator),pct(d?.percent),num(d?.denominator)];}));}
function render(){const year=+$('year').value,sev=$('severity').value,selected=FactorEngine.select(rows,year,sev);pairs=FactorEngine.pairs(selected);const den=mode=>selected.find(r=>r.mode===mode&&r.factor==='Vehicles in collisions with at least 1 RSF')?.denominator;const summary=mode=>selected.find(r=>r.mode===mode&&r.factor==='Vehicles with no RSF')?.percent;
$('status').textContent=year+' · '+sev+' · Great Britain · RAS0702';$('coverage').textContent='Eligible motorcycle denominator: '+num(den('converted'))+' converted CF; '+num(den('direct'))+' directly recorded RSF. No pooled percentage is calculated.';
$('kpis').innerHTML=[['Converted denominator',num(den('converted'))],['Direct denominator',num(den('direct'))],['No factor assigned to motorcycle · converted',pct(summary('converted'))],['No factor assigned to motorcycle · direct',pct(summary('direct'))]].map(([a,b])=>'<div class="kpi"><span>'+a+'</span><strong>'+b+'</strong></div>').join('');
$('table').innerHTML=table(['Factor','Group','Converted CF %','Converted number','Direct RSF %','Direct number'],pairs.map(p=>[p.factor,p.section,pct(p.converted?.percent),num(p.converted?.count),pct(p.direct?.percent),num(p.direct?.count)]));$('export').disabled=!pairs.length;renderTrend();}
$('controls').addEventListener('submit',e=>e.preventDefault());$('controls').addEventListener('change',render);$('factor').addEventListener('change',renderTrend);
$('export').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob(['\uFEFF'+FactorEngine.csv(pairs,$('year').value,$('severity').value)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='dft-motorcycle-factors-'+$('year').value+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
(async()=>{try{const res=await fetch('data/factors.json');if(!res.ok)throw Error('Published summaries unavailable');const data=await res.json();rows=data.rows;const factors=FactorEngine.pairs(FactorEngine.select(rows,2025,'FSC (adjusted)'));$('factor').innerHTML=factors.map(p=>'<option value="'+esc(p.factor)+'">'+esc(p.factor)+'</option>').join('');$('factor').value='Sudden braking or braking in a way unsuitable for conditions';
const c=rows.find(r=>r.kind==='casualty'&&r.mode==='direct'&&r.year===2025&&r.severity==='KSI (adjusted)'&&r.factor.startsWith('Ineffective observation'));
$('context').textContent='In 2025, ineffective observation was recorded somewhere in the collisions accounting for '+pct(c.percent)+' of eligible motorcycle-user adjusted KSI casualties ('+num(c.count)+' of '+num(c.denominator)+', at published precision). This is a different population and unit from the motorcycle-assigned factors above; do not subtract the percentages to estimate other-driver responsibility.';
render();}catch(e){$('error').hidden=false;$('error').textContent='Could not load public factor tables. Please refresh. '+e.message;$('status').textContent='Unavailable';}})();
}
